// 私人预约使用独立版本段；原Interaction visitor不添字段，派生人物索引只由真实约定重建。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "personal_appointment_state.hpp"
#include "resident/domains/interaction/s3_leaf_life_codec.hpp"
#include "resident/domains/interaction/s3_event_time_codec.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "resident/domains/interaction/interaction_source_projection.hpp"
namespace hanmo::resident {namespace {
template<class A>Status contact(A& a,PersonalAppointmentContact& c){a.field("actor_id",c.actor_id);a.field("provider_actor_id",c.provider_actor_id);a.field("session_id",c.session_id);a.field("place_id",c.place_id);a.field("role_id",c.role_id);a.field("dialogue_id",c.dialogue_id);a.field("node_id",c.node_id);return a.field("tick",c.tick);}
template<class A>Status receipt(A& a,std::optional<PersonalAppointmentPlayerReceipt>& v){return a.optional("player_receipt",v,[](auto& child,auto& p){child.field("result_id",p.result_id);child.field("request_actor_id",p.request_actor_id);child.field("request_sequence",p.request_sequence);return child.field("result_revision",p.result_revision);});}
template<class A>Status accepted(A& a,PersonalAppointmentAccepted& v){a.field("fact_id",v.fact_id);a.field("policy_id",v.policy_id);auto r=a.object("contact",[&](auto& child){return contact(child,v.contact);});if(!r.ok)return r;a.field("earliest_tick",v.earliest_tick);a.field("latest_tick",v.latest_tick);a.field("duration_ticks",v.duration_ticks);return receipt(a,v.player_receipt);}
template<class A>Status cancelled(A& a,PersonalAppointmentCancelled& v){a.field("fact_id",v.fact_id);a.field("appointment_id",v.appointment_id);auto r=a.object("contact",[&](auto& child){return contact(child,v.contact);});return r.ok?receipt(a,v.player_receipt):r;}
template<class A>Status started(A& a,PersonalAppointmentStarted& v){a.field("fact_id",v.fact_id);a.field("appointment_id",v.appointment_id);a.field("action_id",v.action_id);auto r=a.object("contact",[&](auto& child){return contact(child,v.contact);});return r.ok?receipt(a,v.player_receipt):r;}
template<class A>Status finished(A& a,PersonalAppointmentFinished& v){a.field("fact_id",v.fact_id);a.field("appointment_id",v.appointment_id);a.field("start_fact_id",v.start_fact_id);a.field("action_id",v.action_id);a.field("tick",v.tick);a.field("success",v.success);a.field("reason",v.reason);return receipt(a,v.player_receipt);}
template<class A>Status state(A& a,PersonalAppointmentState& v){
    a.field("version",v.version);if(v.version!=1&&v.version!=2)return a.reject("UnsupportedPersonalAppointmentVersion");
    auto r=dynamic_codec::table(a,"accepted",v.accepted,[](auto& child,auto& row){return accepted(child,row);});if(!r.ok)return r;
    r=dynamic_codec::table(a,"cancelled",v.cancelled,[](auto& child,auto& row){return cancelled(child,row);});if(!r.ok)return r;
    r=dynamic_codec::table(a,"started",v.started,[](auto& child,auto& row){return started(child,row);});if(!r.ok)return r;
    r=dynamic_codec::table(a,"finished",v.finished,[](auto& child,auto& row){return finished(child,row);});if(!r.ok)return r;
    if(v.version==1)return v.life_sources.empty()&&v.temporal_events.empty()?a.status():a.reject("UnselectedPersonalAppointmentTime2Sources");
    r=dynamic_codec::table(a,"life_sources",v.life_sources,[](auto&c,auto&row){c.object("death_ref",[&](auto&x){return s3_leaf_life_codec::death(x,row.death_ref);});c.field("appointment_id",row.appointment_id);dynamic_codec::enumeration(c,"role",row.role,1);return c.object("effect",[&](auto&x){return s3_leaf_life_codec::fields(x,row.effect,2);});});if(!r.ok)return r;
    return dynamic_codec::table(a,"temporal_events",v.temporal_events,[](auto&c,auto&row){return s3_event_time_codec::fields(c,row);});
}
// 不依赖文本parser，直接构造的typed JSON也必须拒绝递归重键与过量结构。
Status unique(const BoundaryValue& value,std::size_t depth=0){if(depth>CodecVisitor::max_depth)return common_failure("PersonalAppointmentTooDeep");if(const auto* rows=value.as<BoundaryValue::Dict>()){if(rows->size()>CodecVisitor::max_items)return common_failure("PersonalAppointmentTooLarge");std::set<StableId> names;for(const auto& row:*rows){if(!names.insert(row.first).second)return common_failure("DuplicatePersonalAppointmentField",row.first);auto r=unique(row.second,depth+1);if(!r.ok)return r;}}if(const auto* rows=value.as<BoundaryValue::Array>()){if(rows->size()>CodecVisitor::max_items)return common_failure("PersonalAppointmentTooLarge");for(const auto& row:*rows){auto r=unique(row,depth+1);if(!r.ok)return r;}}return common_success();}
}
Outcome<PersonalAppointmentState> decode_personal_appointments(const BoundaryValue& value){auto r=unique(value);if(!r.ok)return {false,{},r.error};PersonalAppointmentState out;dynamic_codec::JsonArchive archive(value);r=state(archive,out);if(r.ok)r=archive.finish();if(!r.ok)return {false,{},r.error};rebuild_personal_appointment_indexes(out);return {true,std::move(out),{}};}
Status emit_personal_appointments_fields(ProjectionWriter&w,const PersonalAppointmentState&v){dynamic_projection::Archive a(w);return state(a,const_cast<PersonalAppointmentState&>(v));}
BoundaryValue encode_personal_appointments(const PersonalAppointmentState& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_personal_appointments_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Status visit_personal_appointments_checkpoint(CodecVisitor& codec,PersonalAppointmentState& value){auto r=state(codec,value);if(r.ok&&codec.reading())rebuild_personal_appointment_indexes(value);return r;}
Status emit_personal_appointment_action_fields(ProjectionWriter&w,const PersonalAppointmentStarted&s){dynamic_projection::Archive a(w);return started(a,const_cast<PersonalAppointmentStarted&>(s));}
BoundaryValue encode_personal_appointment_action(const PersonalAppointmentStarted& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_personal_appointment_action_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Status emit_personal_appointment_fact_fields(ProjectionWriter&w,const PersonalAppointmentState&s,const StableId&id,const FactRecord*expected){dynamic_projection::Archive a(w);Status valid;StableId kind;const StableId*actual_id=nullptr;if(const auto*row=s.accepted.find(id)){valid=accepted(a,const_cast<PersonalAppointmentAccepted&>(*row));kind=personal_appointment_accepted_kind;actual_id=&row->fact_id;}else if(const auto*row=s.cancelled.find(id)){valid=cancelled(a,const_cast<PersonalAppointmentCancelled&>(*row));kind=personal_appointment_cancelled_kind;actual_id=&row->fact_id;}else if(const auto*row=s.started.find(id)){valid=started(a,const_cast<PersonalAppointmentStarted&>(*row));kind=personal_appointment_started_kind;actual_id=&row->fact_id;}else if(const auto*row=s.finished.find(id)){valid=finished(a,const_cast<PersonalAppointmentFinished&>(*row));kind=personal_appointment_finished_kind;actual_id=&row->fact_id;}else return common_failure("MissingPersonalAppointmentPayload",id);if(!valid.ok)return valid;if(expected&&(!actual_id||*actual_id!=id||kind!=expected->kind))return common_failure("PersonalAppointmentFactMismatch",id);w.field("kind",kind);w.text("domain",std::string_view(personal_appointment_module));return w.status();}
Outcome<BoundaryValue> encode_personal_appointment_fact(const PersonalAppointmentState& s,const StableId& id){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_personal_appointment_fact_fields(out,s,id);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
}
